package contacts;

import java.util.Objects;

public final class Member {
    private final String name;
    private Phone phone;
    public Member(String name, String area, String number) {
        Objects.requireNonNull(name, "name");
        if (name.isBlank() || name.codePointCount(0, name.length()) > 60
                || name.indexOf('\r') >= 0 || name.indexOf('\n') >= 0
                || name.indexOf('<') >= 0 || name.indexOf('>') >= 0)
            throw new IllegalArgumentException("name");
        this.name = name;
        this.phone = new Phone(area, number);
    }
    public String displayName() { return name; }
    public String areaCode() { return phone.areaCode(); }
    public String localNumber() { return phone.localNumber(); }
    public String telephone() { return phone.format(); }
    public void changePhone(String nextArea, String nextNumber) {
        phone = new Phone(nextArea, nextNumber);
    }
    public String maskedTelephone() { return phone.masked(); }
}

package contacts;

import java.util.Objects;

/** Immutable owner of phone fields, validation and presentation rules. */
public record Phone(String areaCode, String localNumber) {
    public Phone {
        Objects.requireNonNull(areaCode, "area");
        if (!areaCode.matches("[0-9]{2,4}")) throw new IllegalArgumentException("area");
        Objects.requireNonNull(localNumber, "number");
        if (!localNumber.matches("[0-9]{4,8}")) throw new IllegalArgumentException("number");
    }
    public String format() { return "(" + areaCode + ") " + localNumber; }
    public String masked() {
        return "(" + areaCode + ") " + "*".repeat(localNumber.length() - 2)
            + localNumber.substring(localNumber.length() - 2);
    }
}

package dates;

import java.time.LocalDate;
import java.util.Objects;

/** A complete composition-based local extension, compared with one static helper. */
public record BusinessDate(LocalDate date) {
    public BusinessDate { Objects.requireNonNull(date, "date"); }
    public BusinessDate followingMonday() {
        return new BusinessDate(ForeignDateMethods.followingMonday(date));
    }
}

package dates;

import java.time.LocalDate;
import java.util.Objects;

/** A complete foreign-method comparison using an immutable JDK type. */
public final class ForeignDateMethods {
    private ForeignDateMethods() {}
    public static LocalDate followingMonday(LocalDate date) {
        Objects.requireNonNull(date, "date");
        int forward = 8 - date.getDayOfWeek().getValue();
        return date.plusDays(forward);
    }
}

